SELECT ?person ?personLabel ?birthplace ?birthplaceLabel ?coord ?centuryLabel WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P19 ?birthplace;
          wdt:P569 ?dob.
  ?birthplace wdt:P625 ?coord.

  BIND(YEAR(?dob) AS ?year)
  BIND(
    IF(?year > 0,
      CONCAT(
        STR(1 + FLOOR((?year - 1) / 100)),
        "th century"
      ),
      CONCAT(
        STR(1 + FLOOR((1 - ?year) / 100)),
        "th century BCE"
      )
    ) AS ?centuryLabel
  )

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

