    wd:Q1445522   # Michael
    wd:Q12496859  # Michel
    wd:Q1805772   # Miguel
    wd:Q12308941  # Mikhail
    wd:Q4925477   # Michele
  }
  ?person wdt:P31 wd:Q5;
          wdt:P735 ?givenName;
          wdt:P19 ?birthPlace.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?property ?propertyLabel ?propertyDescription WHERE {
  ?property a wikibase:Property .
  FILTER(NOT EXISTS { ?property rdfs:label ?labelEs FILTER(LANG(?labelEs) = "es") } ||
         NOT EXISTS { ?property schema:description ?descEs FILTER(LANG(?descEs) = "es") })
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (COUNT(DISTINCT ?statement) AS ?count) WHERE {
  ?item ?p ?statement .
  ?property wikibase:claim ?p ;
            wikibase:statementProperty ?ps .
  ?statement ?ps ?value ;
             prov:wasDerivedFrom ?ref .
  ?ref pr:P356 ?doi .
}

SELECT DISTINCT ?image ?cathedral ?cathedralLabel WHERE {
  ?cathedral wdt:P31/wdt:P279* wd:Q2977;      # instance of / subclass of cathedral
             wdt:P17 wd:Q142;                 # country: France
             wdt:P18 ?image.                  # image
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?ingredientLabel (COUNT(DISTINCT ?sandwich) AS ?count) WHERE {
  ?sandwich wdt:P31/wdt:P279* wd:Q28803.
  ?sandwich p:P186 ?statement.
  ?statement ps:P186 ?ingredient.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?ingredient ?ingredientLabel
ORDER BY DESC(?count)
LIMIT 20

SELECT ?item ?itemLabel ?inventoryNumber WHERE {
  ?item wdt:P217 ?inventoryNumber .
  FILTER NOT EXISTS { ?item wdt:P195 ?collection . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?cityHall ?cityHallLabel ?address WHERE {
  ?cityHall wdt:P31/wdt:P279* wd:Q25550691;
            wdt:P17 wd:Q29;
            wdt:P6375 ?address.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?place ?placeLabel ?population ?osmRelationId WHERE {
  ?place wdt:P31/wdt:P279* ?type ;
         wdt:P17 wd:Q35 ;
         wdt:P1082 ?population ;
         wdt:P402 ?osmRelationId .
  VALUES ?type { wd:Q515 wd:Q3957 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?placeLabel

SELECT DISTINCT ?country WHERE {
  wd:Q3995 wdt:P150 ?municipality .            # Basque Country -> contains municipality
  ?municipality wdt:P47 ?country .            # municipality shares border with country
  ?country wdt:P31 wd:Q6256 .                 # country

  FILTER NOT EXISTS {
    wd:Q3995 wdt:P150 ?m2 .
    FILTER NOT EXISTS { ?m2 wdt:P47 ?country }
  }
}

SELECT ?work ?workLabel ?image WHERE {
  ?work wdt:P31/wdt:P279* wd:Q125191;
        wdt:P195 wd:Q1191732;
        wdt:P18 ?image.
  FILTER EXISTS {
    ?work wdt:P170 ?creator.
  }
  FILTER EXISTS {
    ?work wdt:P136 ?genre.
  }
  FILTER(?workDate >= "1801-01-01T00:00:00Z"^^xsd:dateTime && ?workDate < "1901-01-01T00:00:00Z"^^xsd:dateTime)
  ?work wdt:P571 ?workDate.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?date ?stateLabel (SUM(?cases) AS ?cases)
WHERE {
  ?state wdt:P31/wdt:P279* wd:Q35657;
         wdt:P17 wd:Q668.
  ?state p:P1603 ?statement.
  ?statement ps:P1603 ?cases;
             pq:P585 ?date.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?date ?stateLabel
ORDER BY ?date

SELECT DISTINCT ?item ?itemLabel WHERE {
  {
    ?item wdt:P31/wdt:P279* wd:Q8513.
  }
  UNION
  {
    ?item wdt:P31/wdt:P279* wd:Q1622272.
  }
  FILTER NOT EXISTS { ?item wdt:P856 ?officialURL. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?monument ?monumentLabel ?coord ?type ?typeLabel WHERE {
  ?monument wdt:P1435 wd:Q4989906;
            wdt:P625 ?coord;
            wdt:P31 ?type.
  ?type wdt:P279* wd:Q839954.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,sl". }
}

SELECT ?writer ?writerLabel ?signature WHERE {
  ?writer wdt:P31 wd:Q5;
          wdt:P21 wd:Q6581072;
          wdt:P106 wd:Q36180;
          wdt:P103 wd:Q150;
          wdt:P109 ?signature.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?artwork ?artworkLabel WHERE {
  ?artwork wdt:P31/wdt:P279* wd:Q838948 ;
           wdt:P180 wd:Q405 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?grandchild ?grandchildLabel WHERE {
  wd:Q1339 p:P40 ?childStatement .
  ?childStatement ps:P40 ?child ;
                  pq:P1038 wd:Q57194 .
  ?child wdt:P40 ?grandchild .

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?word ?wordLabel WHERE {
  ?word wdt:P31 wd:Q1860;
        wdt:P407 wd:Q1860;
        rdfs:label ?wordLabel.
  FILTER(LANG(?wordLabel) = "en")
  FILTER(REGEX(?wordLabel, "^F....$", "i"))
}

SELECT ?tree ?treeLabel ?coord WHERE {
  ?tree wdt:P31 wd:Q757163;
        wdt:P17 wd:Q219;
        wdt:P625 ?coord.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?inventor ?inventorLabel WHERE {
  ?inventor wdt:P31 wd:Q5;
            wdt:P106 wd:Q205375;
            wdt:P102 wd:Q29468.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?website ?websiteLabel WHERE {
  ?website wdt:P31 wd:Q35127 .
  FILTER NOT EXISTS { ?website wdt:P856 ?officialWebsite . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?externalLink WHERE {
  wd:Q636617 schema:about ?article ;
              schema:isPartOf <https://en.wikipedia.org/> .
  ?article schema:mentions ?externalLink .
  FILTER(isIRI(?externalLink))
  FILTER(STRSTARTS(STR(?externalLink), "http"))
}

SELECT DISTINCT ?organism ?organismLabel WHERE {
  ?organism wdt:P703 wd:Q5880 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?painting ?paintingLabel ?rkdimages ?image WHERE {
  ?painting wdt:P31 wd:Q3305213;
            wdt:P6500 ?rkdimages.
  OPTIONAL { ?painting wdt:P18 ?image. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
LIMIT 200

SELECT ?director ?directorLabel (COUNT(DISTINCT ?film) AS ?filmCount) WHERE {
  VALUES ?actor { wd:Q318028 }
  ?film wdt:P161 ?actor ;
        wdt:P57 ?director .
  FILTER(?director != ?actor)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?director ?directorLabel
ORDER BY DESC(?filmCount)
LIMIT 10

SELECT ?property ?propertyId ?propertyDescription WHERE {
  ?property a wikibase:Property .
  BIND(STRAFTER(STR(?property), "http://www.wikidata.org/entity/") AS ?propertyId)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} ORDER BY ?propertyId

SELECT ?cave ?caveLabel ?coord WHERE {
  ?cave wdt:P31/wdt:P279* wd:Q35509;
        wdt:P1435 wd:Q67310672;
        wdt:P625 ?coord.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  VALUES ?occupation {
    wd:Q723757   # computational biologist
    wd:Q864503   # bioinformatician
  }
  ?person wdt:P31 wd:Q5;
          wdt:P21 wd:Q6581072;
          wdt:P106 ?occupation.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?state ?stateLabel WHERE {
  ?state wdt:P31 wd:Q35657;
         wdt:P17 wd:Q30;
         rdfs:label ?stateLabel.
  FILTER(LANG(?stateLabel) = "en")
  FILTER(CONTAINS(LCASE(?stateLabel), "a"))
}
ORDER BY ?stateLabel

SELECT ?person ?personLabel ?birthplace ?birthplaceLabel ?gender ?genderLabel WHERE {
  ?person wdt:P1343 wd:Q1138524;
          wdt:P31 wd:Q5;
          wdt:P19 ?birthplace;
          wdt:P21 ?gender.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?birthplaceLabel ?genderLabel ?personLabel

SELECT ?satellite ?satelliteLabel ?launchDate WHERE {
  ?satellite wdt:P31 wd:Q26540 ;
             wdt:P31 wd:Q483242 ;
             wdt:P619 ?launchDate .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?launchDate

SELECT ?hillfort ?hillfortLabel ?coord ?status ?statusLabel WHERE {
  ?hillfort wdt:P31/wdt:P279* wd:Q751454;
            wdt:P625 ?coord;
            wdt:P1435 ?status.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?viaduct ?viaductLabel ?heritageDesignation ?heritageDesignationLabel WHERE {
  VALUES ?country { wd:Q145 }
  ?viaduct wdt:P31/wdt:P279* wd:Q774124;
           wdt:P17 ?country;
           wdt:P1435 ?heritageDesignation.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} ORDER BY ?viaductLabel

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5;
          p:P166 ?awardStatement.
  ?awardStatement ps:P166 wd:Q7775540;
                  pq:P585 ?date.
  FILTER(YEAR(?date) = 2016)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?synthesizer ?synthesizerLabel WHERE {
  ?synthesizer wdt:P31/wdt:P279* wd:Q1638294;
               wdt:P176 wd:Q704555.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?library ?libraryLabel ?coord WHERE {
  ?library wdt:P31/wdt:P279* wd:Q7075 ;
           wdt:P17 wd:Q40 ;
           wdt:P625 ?coord .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?place ?placeLabel WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P735 wd:Q1617869;
          wdt:P19 ?place.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?cat ?catLabel WHERE {
  ?cat p:P39 ?statement .
  ?statement ps:P39 wd:Q4771238 .
  ?cat wdt:P31 wd:Q146 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?item ?itemLabel WHERE {
  ?item p:P1343 ?statement .
  ?statement ps:P1343 wd:Q105977910 .
  FILTER NOT EXISTS { ?statement pq:P304 ?pageNumber . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?work ?workLabel ?authorLabel ?inception ?sitelinks WHERE {
  ?work wdt:P31/wdt:P279* wd:Q7725634;
        wdt:P407 wd:Q188;
        wikibase:sitelinks ?sitelinks.
  OPTIONAL { ?work wdt:P50 ?author. }
  OPTIONAL { ?work wdt:P571 ?inception. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinks)
LIMIT 25

SELECT ?heatwave ?heatwaveLabel ?start ?end WHERE {
  ?heatwave wdt:P31 wd:Q25288065 .
  OPTIONAL { ?heatwave wdt:P580 ?start. }
  OPTIONAL { ?heatwave wdt:P582 ?end. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(COALESCE(?end, ?start))
LIMIT 10

SELECT ?country ?countryLabel (COUNT(DISTINCT ?language) AS ?officialLanguageCount)
WHERE {
  ?country wdt:P31 wd:Q6256;
           wdt:P37 ?language.
  FILTER NOT EXISTS { ?country wdt:P31 wd:Q3024240. }  # exclude former countries
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?country ?countryLabel
HAVING (COUNT(DISTINCT ?language) > 1)
ORDER BY DESC(?officialLanguageCount) ?countryLabel

SELECT DISTINCT ?building ?buildingLabel WHERE {
  ?building wdt:P31 ?instanceOf;
            wdt:P17 wd:Q213.
  VALUES ?instanceOf { wd:Q1370598 wd:Q1125381 }
  ?building wdt:P31 wd:Q11315.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?president ?presidentLabel ?signature WHERE {
  ?president wdt:P39 wd:Q30461;
             wdt:P109 ?signature.
  ?president wdt:P27 wd:Q96.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?megalith ?megalithLabel ?coord WHERE {
  ?megalith wdt:P31/wdt:P279* wd:Q1175156;
            wdt:P131* wd:Q3995;
            wdt:P625 ?coord.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?spacecraftLabel ?inspirationLabel WHERE {
  ?spacecraft wdt:P31 wd:Q40218 .
  ?spacecraft wdt:P941 ?inspiration .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?property ?propertyLabel ?coord WHERE {
  ?property wdt:P31/wdt:P279* wd:Q623401 ;
            wdt:P137 wd:Q623566 ;
            wdt:P625 ?coord .
  ?property wdt:P17 wd:Q145 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?car ?carLabel ?length WHERE {
  ?car wdt:P31/wdt:P279* wd:Q1420;
       wdt:P2043 ?length.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?length)
LIMIT 50

SELECT ?painting ?paintingLabel ?image ?height ?width WHERE {
  ?painting wdt:P31 wd:Q3305213;
            wdt:P18 ?image;
            p:P2048 ?heightStatement;
            p:P2049 ?widthStatement.
  ?heightStatement psn:P2048 ?heightNode.
  ?heightNode wikibase:quantityAmount ?height.
  ?widthStatement psn:P2049 ?widthNode.
  ?widthNode wikibase:quantityAmount ?width.
  FILTER(?height > ?width)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?senator ?senatorLabel ?hometown ?hometownLabel WHERE {
  ?senator p:P39 ?statement .
  ?statement ps:P39 wd:Q4416090 ;
             pq:P2937 ?district .
  FILTER NOT EXISTS { ?statement pq:P582 ?endTime . }
  ?district wdt:P17 wd:Q30 .
  OPTIONAL { ?senator wdt:P19 ?hometown . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?settlement ?settlementLabel WHERE {
  ?settlement wdt:P31/wdt:P279* wd:Q486972;
              wdt:P131* wd:Q3995;
              wdt:P1435 wd:Q11684322.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?county1 ?county1Label ?county2 ?county2Label ?countryLabel WHERE {
  VALUES ?country { wd:Q21 wd:Q25 wd:Q22 }  # England, Wales, Scotland

  ?county1 wdt:P31/wdt:P279* wd:Q47168 ;
           wdt:P17 wd:Q145 ;
           wdt:P131 ?country ;
           wdt:P47 ?county2 .

  ?county2 wdt:P31/wdt:P279* wd:Q47168 ;
           wdt:P17 wd:Q145 ;
           wdt:P131 ?country .

  FILTER(?county1 != ?county2)
  FILTER(STR(?county1) < STR(?county2))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel ?deathDate WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P27 wd:Q668;
          wdt:P570 ?deathDate.
  FILTER(YEAR(?deathDate) = 1959)

  {
    ?work wdt:P50 ?person;
          wdt:P6216 wd:Q19652.
  }
  UNION
  {
    ?work wdt:P170 ?person;
          wdt:P6216 wd:Q19652.
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?personLabel

SELECT ?lexeme ?lemma (COUNT(?part) AS ?compoundPartCount) WHERE {
  ?lexeme dct:language wd:Q1860;
          wikibase:lemma ?lemma;
          ontolex:lexicalForm ?form.
  ?form ontolex:representation ?representation.
  ?lexeme wikibase:lexicalCategory ?category.
  OPTIONAL { ?lexeme wdt:P5238 ?part. }
}
GROUP BY ?lexeme ?lemma
ORDER BY DESC(?compoundPartCount)
LIMIT 100

SELECT ?human ?humanLabel WHERE {
  ?human wdt:P31 wd:Q5 .
  FILTER NOT EXISTS { ?human wdt:P40 ?child . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?river ?riverLabel WHERE {
  ?river wdt:P31/wdt:P279* wd:Q4022;
         wdt:P17 wd:Q51.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?library ?libraryLabel ?coord WHERE {
  ?library wdt:P31/wdt:P279* wd:Q7075;
           wdt:P17 wd:Q40;
           wdt:P625 ?coord.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?politician ?politicianLabel WHERE {
  ?politician wdt:P31 wd:Q5;
              wdt:P106 wd:Q82955;
              wdt:P509 ?causeOfDeath.
  ?causeOfDeath wdt:P279* wd:Q12078.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?site ?siteLabel ?sitelinks WHERE {
  ?site wdt:P1435 ?heritageStatus;
        wikibase:sitelinks ?sitelinks.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?sitelinks)
LIMIT 100

SELECT ?artist ?artistLabel WHERE {
  ?artist wdt:P31 wd:Q5;
          wdt:P27 wd:Q31;
          wdt:P106 wd:Q483501;
          wdt:P570 ?deathDate.
  FILTER(YEAR(?deathDate) = 1949)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?school ?schoolLabel ?studentCount WHERE {
  {
    SELECT ?school (COUNT(DISTINCT ?student) AS ?studentCount) WHERE {
      ?student wdt:P69 ?school.
      ?school wdt:P31/wdt:P279* wd:Q2385804.
    }
    GROUP BY ?school
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?studentCount)
LIMIT 10

SELECT DISTINCT ?country ?countryLabel WHERE {
  {
    SELECT ?university WHERE {
      ?university wdt:P31/wdt:P279* wd:Q3918 ;
                  wdt:P17 wd:Q117 ;
                  wdt:P31 ?type .
      VALUES ?type { wd:Q3918 wd:Q189004 wd:Q2385804 }
      OPTIONAL { ?university wdt:P1128 ?students }
    }
    ORDER BY DESC(?students)
    LIMIT 3
  }

  ?person wdt:P108|wdt:P1416|wdt:P463 ?university ;
          wdt:P27 ?country .

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?birthDate ?deathDate WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P27 wd:Q30;
          wdt:P21 wd:Q6581097;
          p:P569 ?birthStmt;
          p:P570 ?deathStmt.

  ?birthStmt ps:P569 ?birthDate;
             wikibase:timePrecision ?birthPrecision.
  ?deathStmt ps:P570 ?deathDate;
             wikibase:timePrecision ?deathPrecision.

  FILTER(?birthDate >= "1875-01-01T00:00:00Z"^^xsd:dateTime &&
         ?birthDate <  "1931-01-01T00:00:00Z"^^xsd:dateTime)
  FILTER(?birthPrecision = 9)
  FILTER(?deathPrecision = 11)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?town ?townLabel WHERE {
  ?street wdt:P31/wdt:P279* wd:Q79007;
          wdt:P131 wd:Q90;
          wdt:P138 ?town.
  ?town wdt:P31/wdt:P279* wd:Q3957;
        wdt:P17 wd:Q142.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?state ?stateLabel ?coord ?iNaturalist WHERE {
  ?state wdt:P31 wd:Q1221156;
