  wd:Q5448399 p:P1346 ?awardStatement .
  ?awardStatement ps:P1346 ?winner .
  OPTIONAL { ?winner wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

