  {
    ?language wdt:P31 wd:Q34770 .
  }
  UNION
  {
    ?language wdt:P31 wd:Q1288568 .
  }
  ?language wdt:P18 ?languageImage .
  ?dialect wdt:P31 wd:Q33215 ;
