  ?parish wdt:P31 wd:Q1149652;
          wdt:P131 ?county;
          wdt:P625 ?coord.
  ?county wdt:P31 wd:Q735428.
  ?county wdt:P131* wd:Q3224.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
