       pq:P580 ?start1 .
  ?ps2 ps:P39 ?position2 ;
       pq:P768 ?otherSeat ;
       pq:P580 ?start2 .
  FILTER(?seat != ?otherSeat)
  FILTER(YEAR(?start1) = ?year)
  FILTER(YEAR(?start2) = ?year)
  FILTER(?year >= 1830 && ?year <= 1910)

  ?position1 wdt:P279* wd:Q16707842 .
  ?position2 wdt:P279* wd:Q16707842 .

  ?seat wdt:P17 wd:Q145 .
  ?otherSeat wdt:P17 wd:Q145 .
}
GROUP BY ?year
ORDER BY ?year

