  FILTER(?birthDate >= "1590-01-01T00:00:00Z"^^xsd:dateTime &&
         ?birthDate < "1751-01-01T00:00:00Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

