SELECT DISTINCT ?languageLabel WHERE {
  VALUES ?item { wd:Q137 wd:Q12518 }

  ?item rdfs:label ?label .
  BIND(LANG(?label) AS ?lang)

  FILTER(?lang != "")

  {
    SELECT ?lang
    WHERE {
      VALUES ?item2 { wd:Q137 wd:Q12518 }
      ?item2 rdfs:label ?label2 .
      BIND(LANG(?label2) AS ?lang)
      FILTER(?lang != "")
    }
    GROUP BY ?lang
    HAVING(COUNT(DISTINCT ?item2) = 2)
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
  ?language wdt:P218 ?lang .
}

