SELECT ?word ?wordLabel WHERE {
  ?word wdt:P31 wd:Q1084;
        rdfs:label ?wordLabel.
  FILTER(LANG(?wordLabel) = "en")
  BIND(STRLEN(?wordLabel) AS ?len)
  {
    SELECT (MAX(?l) AS ?maxLen) WHERE {
      ?w wdt:P31 wd:Q1084;
         rdfs:label ?lab.
      FILTER(LANG(?lab) = "en")
      BIND(STRLEN(?lab) AS ?l)
    }
  }
  FILTER(?len = ?maxLen)
  BIND(?wordLabel AS ?word)
}
ORDER BY ?wordLabel

