SELECT DISTINCT ?actor ?actorLabel ?character ?characterLabel WHERE {
  ?actor wdt:P31 wd:Q5;
         wdt:P21 wd:Q6581097;
         p:P161 ?cast1, ?cast2.

  ?cast1 ps:P161 ?actor;
         pq:P453 ?character;
         pq:P1545 ?ord1.
  ?cast2 ps:P161 ?actor;
         pq:P453 ?character;
         pq:P1545 ?ord2.

  FILTER(?cast1 != ?cast2)
  FILTER(?ord1 != ?ord2)

  ?film1 p:P161 ?cast1;
         wdt:P31 wd:Q11424.
  ?film2 p:P161 ?cast2;
         wdt:P31 wd:Q11424.

  ?film1 wdt:P179 ?series.
  ?film2 wdt:P179 ?series.

  ?series wdt:P31/wdt:P279* wd:Q24856.

  FILTER(?film1 != ?film2)

  ?film1 wdt:P577 ?date1.
  ?film2 wdt:P577 ?date2.
  BIND(YEAR(?date1) AS ?y1)
  BIND(YEAR(?date2) AS ?y2)
  FILTER(ABS(?y2 - ?y1) >= 20)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

