  {
    SELECT ?event (COUNT(DISTINCT ?game) AS ?announcedGamesCount) WHERE {
      ?game wdt:P31/wdt:P279* wd:Q7889;
            p:P577 ?pubStmt.
      ?pubStmt ps:P577 ?date;
               pq:P291 ?event.
    }
    GROUP BY ?event
  }
  {
    SELECT (MAX(?count) AS ?maxCount) WHERE {
      {
        SELECT ?event (COUNT(DISTINCT ?game) AS ?count) WHERE {
          ?game wdt:P31/wdt:P279* wd:Q7889;
                p:P577 ?pubStmt.
          ?pubStmt ps:P577 ?date;
                   pq:P291 ?event.
        }
        GROUP BY ?event
      }
    }
  }
  FILTER(?announcedGamesCount = ?maxCount)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?discoveryCenturyLabel WHERE {
  ?object wdt:P195 wd:Q3403983;
          wdt:P31/wdt:P279* wd:Q220659;
          p:P575 ?discoveryStatement.
  ?discoveryStatement ps:P575 ?discoveryDate.
  OPTIONAL { ?discoveryStatement pq:P4241 ?discoveryCentury. }
  BIND(
    IF(BOUND(?discoveryCentury),
       ?discoveryCentury,
       IF(YEAR(?discoveryDate) < 0,
          IRI(CONCAT("http://www.wikidata.org/entity/Q", STR(100 + FLOOR((ABS(YEAR(?discoveryDate)) - 1) / 100)))),
          IRI(CONCAT("http://www.wikidata.org/entity/Q", STR(101 + FLOOR((YEAR(?discoveryDate) - 1) / 100))))
       )
    ) AS ?discoveryCenturyEntity
  )
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". ?discoveryCenturyEntity rdfs:label ?discoveryCenturyLabel. }
}

