    wd:Q538      # Oceania
  }

  {
    SELECT ?continent (MAX(?len) AS ?maxLen) WHERE {
      VALUES ?continent {
        wd:Q15
        wd:Q46
        wd:Q48
        wd:Q49
        wd:Q18
        wd:Q51
        wd:Q538
      }
      ?river wdt:P31/wdt:P279* wd:Q4022;
             wdt:P30 ?continent;
             wdt:P2043 ?len.
    }
    GROUP BY ?continent
  }

  ?river wdt:P31/wdt:P279* wd:Q4022;
         wdt:P30 ?continent;
         wdt:P2043 ?length.
  FILTER(?length = ?maxLen)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?continentLabel ?riverLabel

