SELECT ?country ?countryLabel (AVG(?weightKg) AS ?avgWeight)
WHERE {
  ?player wdt:P31 wd:Q5;
          wdt:P54 ?team;
          p:P106 ?stmt.
  ?stmt ps:P106 wd:Q937857;
        pq:P642 wd:Q19317.
  ?player wdt:P2067 ?weightVal.
  BIND(
    IF(DATATYPE(?weightVal) = xsd:decimal || DATATYPE(?weightVal) = xsd:double || DATATYPE(?weightVal) = xsd:float || DATATYPE(?weightVal) = xsd:integer,
       xsd:decimal(?weightVal),
       xsd:decimal(?weightVal)
    ) AS ?weightKg
  )
  ?team wdt:P31 wd:Q6979593;
        wdt:P17 ?country.
  FILTER EXISTS {
    ?team p:P3450 ?participationStmt.
    ?participationStmt ps:P3450 wd:Q284163;
                       pq:P585 ?date.
    FILTER(YEAR(?date) = 2022)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?country ?countryLabel
HAVING (AVG(?weightKg) > 80)
ORDER BY DESC(?avgWeight)

