SELECT ?award ?awardLabel ?femaleRecipients ?totalRecipients ?femalePercentage WHERE {
  {
    SELECT ?award (COUNT(DISTINCT ?female) AS ?femaleRecipients) (COUNT(DISTINCT ?recipient) AS ?totalRecipients)
           ((100.0 * COUNT(DISTINCT ?female)) / COUNT(DISTINCT ?recipient) AS ?femalePercentage)
    WHERE {
      ?recipient p:P166 ?awardStmt .
      ?awardStmt ps:P166 ?award .
      OPTIONAL { ?recipient wdt:P21 ?sex . }
      BIND(IF(BOUND(?sex) && ?sex = wd:Q6581072, ?recipient, UNDEF) AS ?female)
    }
    GROUP BY ?award
    HAVING(COUNT(DISTINCT ?recipient) > 0)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?femalePercentage) DESC(?femaleRecipients)
LIMIT 100

