  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?form ?formLabel WHERE {
  ?form wdt:P31 wd:Q1049839;
        wdt:P407 wd:Q9027.
  FILTER NOT EXISTS { ?form p:P5831 ?exampleStmt. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?subclass ?subclassLabel WHERE {
  ?subclass wdt:P279 wd:Q14001 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (ROUND((100 * ?women / ?total) * 100) / 100 AS ?percentageWomen)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?person) AS ?total)
    WHERE {
      ?person wdt:P166 ?award .
      ?award wdt:P31/wdt:P279* wd:Q7191 .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?woman) AS ?women)
    WHERE {
      ?woman wdt:P166 ?award .
      ?award wdt:P31/wdt:P279* wd:Q7191 .
      ?woman wdt:P21 wd:Q6581072 .
    }
  }
}

SELECT ?article ?articleLabel ?sitelinksCount WHERE {
  ?article schema:about ?item ;
           schema:isPartOf <https://en.wikipedia.org/> .
  ?item wdt:P31/wdt:P279* wd:Q7417751 ;
        wikibase:sitelinks ?sitelinksCount .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinksCount)

SELECT DISTINCT ?work ?workLabel WHERE {
  {
    ?work wdt:P31 wd:Q11424 .
  }
  UNION
  {
    ?work wdt:P31/wdt:P279* wd:Q5398426 .
  }
  ?work wdt:P136 wd:Q24925 .
  ?work wdt:P161 ?actor .
  ?actor wdt:P19 ?birthPlace .
  ?birthPlace wdt:P131* wd:Q24826 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?agency ?agencyLabel WHERE {
  ?agency wdt:P31/wdt:P279* wd:Q327333;   # instance of/subclass of government agency
          wdt:P17 wd:Q145.                # country = United Kingdom
  OPTIONAL { ?agency wdt:P131* wd:Q22. }  # located in the administrative territorial entity Scotland
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?collection ?collectionLabel ?officialWebsite WHERE {
  ?collection wdt:P31/wdt:P279* wd:Q2604588;
              wdt:P856 ?officialWebsite.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?disease ?diseaseLabel ?minIncubation ?maxIncubation WHERE {
  ?disease wdt:P31/wdt:P279* wd:Q18123741.
  ?disease p:P3488 ?minStmt, ?maxStmt.

  ?minStmt ps:P3488 ?minIncubation;
           pq:P642 wd:Q5;
           wikibase:rank wd:PreferredRank.
  ?maxStmt ps:P3488 ?maxIncubation;
           pq:P642 wd:Q5;
           wikibase:rank wd:NormalRank.

  FILTER(?minIncubation <= ?maxIncubation)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?station ?stationLabel WHERE {
  {
    SELECT ?route1 ?route2 (MIN(?totalStops) AS ?minStops) WHERE {
      ?route1 wdt:P31/wdt:P279* wd:Q728937;
              p:P527 ?st1.
      ?st1 ps:P527 wd:Q5273608;
           pq:P1545 ?idx1.

      ?route2 wdt:P31/wdt:P279* wd:Q728937;
              p:P527 ?st2.
      ?st2 ps:P527 wd:Q1993464;
           pq:P1545 ?idx2.

      FILTER(?route1 = ?route2)
      BIND(xsd:integer(?idx2) - xsd:integer(?idx1) - 1 AS ?totalStops)
      FILTER(?totalStops >= 0)
    }
    GROUP BY ?route1 ?route2
    ORDER BY ?minStops
    LIMIT 1
  }

  ?route1 p:P527 ?midStmt.
  ?midStmt ps:P527 ?station;
           pq:P1545 ?midIdx.

  ?route1 p:P527 ?startStmt.
  ?startStmt ps:P527 wd:Q5273608;
             pq:P1545 ?startIdx.

  ?route1 p:P527 ?endStmt.
  ?endStmt ps:P527 wd:Q1993464;
           pq:P1545 ?endIdx.

  FILTER(xsd:integer(?midIdx) > xsd:integer(?startIdx) && xsd:integer(?midIdx) < xsd:integer(?endIdx))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} ORDER BY xsd:integer(?midIdx)

SELECT ?person ?personLabel ?birthplace ?birthplaceLabel ?coord WHERE {
  ?person wdt:P119 wd:Q311 ;
          wdt:P19 ?birthplace .
  ?birthplace wdt:P625 ?coord .
