  ?player p:P1344 ?participationStatement .
  ?participationStatement ps:P1344 ?tournament ;
                          pq:P1352 ?ranking .
  ?ranking ps:P1352 wd:Q5404515 ;
           pq:P1114 ?goals .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?goals) ?playerLabel

SELECT DISTINCT ?workplace ?workplaceLabel ?coord WHERE {
  wd:Q718318 p:P108 ?employmentStatement .
  ?employmentStatement ps:P108 ?workplace .
  ?workplace wdt:P625 ?coord .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
