SELECT DISTINCT ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P21 wd:Q6581072;
          wdt:P69 wd:Q34433;
          wdt:P27 ?country.
  FILTER(?country != wd:Q145)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?birthDecade (COUNT(DISTINCT ?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P19 ?birthPlace;
          wdt:P20 ?deathPlace;
          wdt:P569 ?birthDate.
  ?birthPlace wdt:P17 wd:Q213.
  ?deathPlace wdt:P17 wd:Q183.
  BIND((YEAR(?birthDate) - (YEAR(?birthDate) MOD 10)) AS ?birthDecade)
}
GROUP BY ?birthDecade
ORDER BY ?birthDecade

SELECT DISTINCT ?monarchLabel ?causeOfDeathLabel WHERE {
  ?monarch wdt:P31 wd:Q5;
           wdt:P27 wd:Q145;
           wdt:P39 ?position;
           wdt:P509 ?causeOfDeath.
  ?position wdt:P279* wd:Q18810062.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
