SELECT ?subjectLabel (COUNT(DISTINCT ?artwork) AS ?count) WHERE {
  VALUES ?collection { wd:Q657415 wd:Q635257 }
  ?artwork wdt:P195 ?collection ;
           wdt:P180 ?subject .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?subject ?subjectLabel
ORDER BY DESC(?count)
