SELECT ?languageLabel (COUNT(DISTINCT ?album) AS ?numberOfAlbums) WHERE {
  ?album wdt:P31 wd:Q482994 ;
         wdt:P407 ?language .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?languageLabel
ORDER BY DESC(?numberOfAlbums)

SELECT DISTINCT ?country1Label ?capital1Label ?country2Label ?capital2Label ?distance WHERE {
  ?country1 wdt:P31 wd:Q3624078;
            wdt:P36 ?capital1.
  ?country2 wdt:P31 wd:Q3624078;
            wdt:P36 ?capital2.
  FILTER(?country1 != ?country2)
  FILTER(STR(?country1) < STR(?country2))
  FILTER NOT EXISTS { ?country1 wdt:P47 ?country2 }
  FILTER NOT EXISTS { ?country2 wdt:P47 ?country1 }

  ?capital1 wdt:P625 ?coord1.
  ?capital2 wdt:P625 ?coord2.

  BIND(geof:distance(?coord1, ?coord2) AS ?distance)
  FILTER(?distance < 200)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distance

SELECT DISTINCT ?artwork ?artworkLabel ?image WHERE {
  ?artwork wdt:P195 wd:Q6406104;
           wdt:P31/wdt:P279* wd:Q838948;
           wdt:P18 ?image.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?software ?softwareLabel (UCASE(SUBSTR(?softwareLabel, 1, 1)) AS ?firstLetter) WHERE {
  ?software wdt:P31/wdt:P279* wd:Q341;
            rdfs:label ?softwareLabel.
  FILTER(LANG(?softwareLabel) = "en")
}
