SELECT DISTINCT ?museum ?museumLabel ?location ?distance WHERE {
  wd:Q81175 wdt:P625 ?cesisCoord .

  SERVICE wikibase:around {
    ?museum wdt:P31/wdt:P279* wd:Q33506 ;
            wdt:P625 ?location .
    bd:serviceParam wikibase:center ?cesisCoord .
    bd:serviceParam wikibase:radius "25" .
    bd:serviceParam wikibase:distance ?distance .
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distance

SELECT ?categoryLabel ?genderLabel (COUNT(DISTINCT ?winner) AS ?winnerCount) WHERE {
  ?winner wdt:P166 ?nobelPrize .
  ?nobelPrize wdt:P31 wd:Q7191 .
  ?winner wdt:P21 ?gender .
  ?nobelPrize wdt:P361 ?category .

