SELECT DISTINCT ?artist ?artistLabel ?deathPlace ?deathPlaceLabel WHERE {
  ?artist wdt:P31 wd:Q5;
          wdt:P106 ?occupation;
          wdt:P20 ?deathPlace.
  ?occupation wdt:P279* wd:Q483501.
  ?deathPlace wdt:P31/wdt:P279* wd:Q39614.

  VALUES ?campClass { wd:Q39614 wd:Q16917 }
  ?deathPlace wdt:P31/wdt:P279* ?campClass.

  ?artist wdt:P570 ?dateOfDeath.
  FILTER(?dateOfDeath >= "1939-09-01T00:00:00Z"^^xsd:dateTime && ?dateOfDeath <= "1945-09-02T23:59:59Z"^^xsd:dateTime)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

