SELECT ?person ?personLabel ?mentionCount WHERE {
  {
    SELECT ?person (COUNT(DISTINCT ?article) AS ?mentionCount) WHERE {
      ?person wdt:P31 wd:Q5;
              wdt:P570 ?deathDate.
      FILTER(YEAR(?deathDate) = 2018)

      ?article schema:about ?topic;
               schema:isPartOf ?site.
      FILTER(REGEX(STR(?site), "^https://[a-z]+\\.wikipedia\\.org/$"))

      ?article schema:mentions ?person.
    }
    GROUP BY ?person
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?mentionCount)
LIMIT 100

