SELECT ?river ?riverLabel ?length WHERE {
  {
    SELECT ?river (MAX(?len) AS ?length) WHERE {
      ?river wdt:P31/wdt:P279* wd:Q4022;
             wdt:P17 wd:Q142;
             wdt:P2043 ?len.
      FILTER NOT EXISTS {
        ?dept wdt:P31 wd:Q6465;
              wdt:P17 wd:Q142;
              rdfs:label ?deptLabel.
        FILTER(LANG(?deptLabel) = "fr")
        ?river rdfs:label ?riverLabelFr.
        FILTER(LANG(?riverLabelFr) = "fr")
        FILTER(LCASE(?deptLabel) = LCASE(CONCAT(STR(?riverLabelFr), " ", "department")) || LCASE(?deptLabel) = LCASE(?riverLabelFr))
      }
    }
    GROUP BY ?river
  }
  {
    SELECT (MAX(?length2) AS ?maxLength) WHERE {
      ?river2 wdt:P31/wdt:P279* wd:Q4022;
              wdt:P17 wd:Q142;
              wdt:P2043 ?length2.
      FILTER NOT EXISTS {
        ?dept2 wdt:P31 wd:Q6465;
               wdt:P17 wd:Q142;
               rdfs:label ?deptLabel2.
        FILTER(LANG(?deptLabel2) = "fr")
        ?river2 rdfs:label ?riverLabelFr2.
        FILTER(LANG(?riverLabelFr2) = "fr")
        FILTER(LCASE(?deptLabel2) = LCASE(CONCAT(STR(?riverLabelFr2), " ", "department")) || LCASE(?deptLabel2) = LCASE(?riverLabelFr2))
      }
    }
  }
  FILTER(?length = ?maxLength)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,fr". }
}

