SELECT ?property ?propertyLabel (COUNT(*) AS ?frequency) WHERE {
  ?library wdt:P31 wd:Q7075 .
  ?library ?p ?value .
  FILTER(STRSTARTS(STR(?p), STR(p:)) || STRSTARTS(STR(?p), STR(ps:)) || STRSTARTS(STR(?p), STR(pq:)) )
  BIND(
    IRI(
      REPLACE(
        REPLACE(
          REPLACE(STR(?p), STR(p:), STR(wd:)),
          STR(ps:), STR(wd:)
        ),
        STR(pq:), STR(wd:)
      )
    ) AS ?property
  )
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?property ?propertyLabel
ORDER BY DESC(?frequency)

SELECT DISTINCT ?scene ?sceneLabel WHERE {
  wd:Q68275853 wdt:P180 ?scene .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?stage ?stageLabel WHERE {
  ?stage wdt:P31 wd:Q507370 ;
         wdt:P361 wd:Q43670 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?subdivision ?subdivisionLabel ?country ?countryLabel ?population WHERE {
  ?subdivision wdt:P31/wdt:P279* wd:Q10864048 ;
               wdt:P17 ?country ;
               wdt:P1082 ?population .
  FILTER NOT EXISTS { ?subdivision wdt:P194 ?legislativeBody . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?population)

SELECT ?propertyTypeLabel (COUNT(?prop) AS ?frequency) (SAMPLE(?prop) AS ?exampleProperty) (SAMPLE(?propLabel) AS ?examplePropertyLabel) WHERE {
  ?prop wikibase:propertyType ?propertyType .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} GROUP BY ?propertyType ?propertyTypeLabel
ORDER BY DESC(?frequency)

SELECT DISTINCT ?songTitle WHERE {
  ?song wdt:P31/wdt:P279* wd:Q7366;
        rdfs:label ?songTitle.
  ?givenName wdt:P31 wd:Q11879590;
             rdfs:label ?songTitle.
  FILTER(LANG(?songTitle) = "en")
}

SELECT DISTINCT ?property ?propertyLabel ?formatterURL WHERE {
  ?property wikibase:propertyType wikibase:ExternalId .
  OPTIONAL { ?property wdt:P1630 ?formatterURL . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?propertyLabel

SELECT DISTINCT ?variant ?variantLabel ?pubmedID WHERE {
  ?variant wdt:P31/wdt:P279* wd:Q1962970.
  ?variant p:P698 ?pubmedStmt.
  ?pubmedStmt ps:P698 ?pubmedID.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?state ?stateLabel ?song ?songLabel WHERE {
  ?state wdt:P31 wd:Q35657;
         p:P2853 ?statement.
  ?statement ps:P2853 ?song;
             pq:P518 wd:Q853149.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
