SELECT ?lastNameLabel (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P734 ?lastName.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?lastName ?lastNameLabel
ORDER BY DESC(?count)
LIMIT 100

SELECT ?deathCentury (GROUP_CONCAT(DISTINCT ?personLabel; separator=", ") AS ?people) WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P27 wd:Q29;
          wdt:P569 ?birthDate;
          wdt:P570 ?deathDate;
          wdt:P19 ?birthplace.
  ?person wdt:P172 wd:Q806.
  FILTER EXISTS {
    ?article schema:about ?person;
             schema:isPartOf <https://en.wikipedia.org/>.
  }
  BIND(CONCAT(
    STR(1 + FLOOR((YEAR(?deathDate) - 1) / 100)),
    IF((1 + FLOOR((YEAR(?deathDate) - 1) / 100)) % 10 = 1 && (1 + FLOOR((YEAR(?deathDate) - 1) / 100)) != 11, "st century",
      IF((1 + FLOOR((YEAR(?deathDate) - 1) / 100)) % 10 = 2 && (1 + FLOOR((YEAR(?deathDate) - 1) / 100)) != 12, "nd century",
        IF((1 + FLOOR((YEAR(?deathDate) - 1) / 100)) % 10 = 3 && (1 + FLOOR((YEAR(?deathDate) - 1) / 100)) != 13, "rd century", "th century")
      )
    )
  ) AS ?deathCentury)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?deathCentury
ORDER BY xsd:integer(STRBEFORE(?deathCentury, " "))

