SELECT ?occupation ?occupationLabel ?maleCount ?femaleCount ?imbalanceRatio WHERE {
  {
    SELECT ?occupation
           (SUM(?male) AS ?maleCount)
           (SUM(?female) AS ?femaleCount)
           (IF((SUM(?male) + SUM(?female)) > 0,
               ABS(SUM(?male) - SUM(?female)) / (SUM(?male) + SUM(?female)),
               0) AS ?imbalanceRatio)
    WHERE {
      ?person wdt:P31 wd:Q5;
              wdt:P27 wd:Q30;
              wdt:P106 ?occupation;
              wdt:P21 ?gender.
      VALUES ?genderMale { wd:Q6581097 }
      VALUES ?genderFemale { wd:Q6581072 }
      BIND(IF(?gender = ?genderMale, 1, 0) AS ?male)
      BIND(IF(?gender = ?genderFemale, 1, 0) AS ?female)
    }
    GROUP BY ?occupation
    HAVING ((SUM(?male) + SUM(?female)) >= 50)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?imbalanceRatio) DESC(?maleCount + ?femaleCount)
LIMIT 25

