SELECT ?occupationLabel (COUNT(DISTINCT ?person) AS ?count) WHERE {
  ?person wdt:P106 ?occupation;
          wdt:P31 ?instance.
  VALUES ?instance { wd:Q5 }

  ?person p:P31 ?statement.
  ?statement ps:P31 wd:Q5.

  {
    ?person wdt:P27 wd:Q22.
  }
  UNION
  {
    ?person wdt:P495 wd:Q22.
  }
  UNION
  {
    ?person wdt:P19 ?birthPlace.
    ?birthPlace wdt:P131* wd:Q22.
  }
  UNION
  {
    ?person wdt:P20 ?deathPlace.
    ?deathPlace wdt:P131* wd:Q22.
  }

  {
    ?person wdt:P1830 ?crime.
    ?crime rdfs:label ?crimeLabel.
    FILTER(LANG(?crimeLabel) = "en")
    FILTER(CONTAINS(LCASE(?crimeLabel), "witch"))
  }
  UNION
  {
    ?person wdt:P921 ?topic.
    ?topic rdfs:label ?topicLabel.
    FILTER(LANG(?topicLabel) = "en")
    FILTER(CONTAINS(LCASE(?topicLabel), "witch"))
  }
  UNION
  {
    ?person schema:description ?desc.
    FILTER(LANG(?desc) = "en")
    FILTER(CONTAINS(LCASE(?desc), "accused witch"))
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?occupationLabel
ORDER BY DESC(?count)

