SELECT ?country ?countryLabel ?capital ?capitalLabel WHERE {
  ?country wdt:P31 wd:Q6256;
           wdt:P36 ?capital.

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }

  FILTER(LANG(?countryLabel) = "en")
  FILTER(LANG(?capitalLabel) = "en")

  BIND(LCASE(REPLACE(?countryLabel, "[^A-Za-z]", "")) AS ?countryName)
  BIND(LCASE(REPLACE(?capitalLabel, "[^A-Za-z]", "")) AS ?capitalName)

  FILTER(STRLEN(?capitalName) > 0)

  FILTER NOT EXISTS {
    VALUES ?letter { "a" "b" "c" "d" "e" "f" "g" "h" "i" "j" "k" "l" "m"
                     "n" "o" "p" "q" "r" "s" "t" "u" "v" "w" "x" "y" "z" }
    BIND(STRLEN(REPLACE(?capitalName, CONCAT("[^", ?letter, "]"), "")) AS ?capCount)
    BIND(STRLEN(REPLACE(?countryName, CONCAT("[^", ?letter, "]"), "")) AS ?countryCount)
    FILTER(?capCount > ?countryCount)
  }
}
ORDER BY ?countryLabel

