SELECT ?institution ?institutionLabel WHERE {
  {
    SELECT ?conferenceSeries WHERE {
      VALUES ?conferenceSeriesLabel { "#vBIB" }
      ?conferenceSeries rdfs:label ?conferenceSeriesLabel .
      FILTER(LANG(?conferenceSeriesLabel) = "en")
    }
  }
  {
    SELECT ?institution (COUNT(DISTINCT ?event) AS ?instEventCount) WHERE {
      {
        SELECT ?event WHERE {
          ?event wdt:P179 ?conferenceSeries .
        }
      }
      ?work wdt:P1433 ?event ;
            wdt:P50 ?author .
      ?author wdt:P108 ?institution .
    }
    GROUP BY ?institution
  }
  {
    SELECT (COUNT(DISTINCT ?allEvent) AS ?totalEventCount) WHERE {
      ?allEvent wdt:P179 ?conferenceSeries .
    }
  }
  FILTER(?instEventCount = ?totalEventCount)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

