  OPTIONAL { ?formEntity prov:wasDerivedFrom/pr:P248 ?sourceForm. }
  OPTIONAL { ?senseEntity prov:wasDerivedFrom/pr:P248 ?sourceSense. }
  BIND(COALESCE(?sourceForm, ?sourceSense) AS ?source)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,sv". }
} LIMIT 100

SELECT ?composer ?composerLabel ?tonality ?tonalityLabel (COUNT(?work) AS ?workCount) WHERE {
  {
    SELECT ?composer (MAX(?count) AS ?maxCount) WHERE {
      {
        SELECT ?composer ?tonality (COUNT(?work) AS ?count) WHERE {
          ?work wdt:P86 ?composer;
                wdt:P826 ?tonality.
          ?composer wdt:P106 wd:Q36834.
        }
        GROUP BY ?composer ?tonality
      }
    }
    GROUP BY ?composer
  }
  {
    SELECT ?composer ?tonality (COUNT(?work) AS ?workCount) WHERE {
      ?work wdt:P86 ?composer;
            wdt:P826 ?tonality.
      ?composer wdt:P106 wd:Q36834.
    }
    GROUP BY ?composer ?tonality
  }
  FILTER(?workCount = ?maxCount)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?composer ?composerLabel ?tonality ?tonalityLabel ?workCount
ORDER BY ?composerLabel ?tonalityLabel

