SELECT ?president ?presidentLabel ?startDate ?birthDate ?ageAtStart WHERE {
  ?president wdt:P31 wd:Q5;
             wdt:P39 wd:Q11696;
             wdt:P27 wd:Q30;
             p:P39 ?statement.
  ?statement ps:P39 wd:Q11696;
             pq:P580 ?startDate.
  ?president wdt:P569 ?birthDate.

  BIND(YEAR(?startDate) - YEAR(?birthDate) -
       IF((MONTH(?startDate) < MONTH(?birthDate)) ||
          (MONTH(?startDate) = MONTH(?birthDate) && DAY(?startDate) < DAY(?birthDate)),
          1, 0) AS ?ageAtStart)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?startDate

