           rdfs:label ?nativeName.
  ?country wdt:P30 wd:Q46.
  FILTER(LANG(?nativeName) = SUBSTR(STR(?lang), STRLEN(STR(?lang)) - 1))
  FILTER(REGEX(?iso2, "^[A-Z]{2}$"))
  BIND(LCASE(?iso2) AS ?isoLower)
