SELECT ?country ?countryLabel ?dayLabel (COUNT(?election) AS ?electionCount) WHERE {
  {
    SELECT ?country ?day (COUNT(?election) AS ?count) WHERE {
      ?election wdt:P31/wdt:P279* wd:Q40231;
                wdt:P17 ?country;
                wdt:P585 ?date.
      BIND(WEEKDAY(?date) AS ?weekdayNum)
      BIND(
        IF(?weekdayNum = 0, wd:Q127,
        IF(?weekdayNum = 1, wd:Q128,
        IF(?weekdayNum = 2, wd:Q129,
        IF(?weekdayNum = 3, wd:Q130,
        IF(?weekdayNum = 4, wd:Q131,
        IF(?weekdayNum = 5, wd:Q132, wd:Q133))))))
        AS ?day
      )
    }
    GROUP BY ?country ?day
  }
  {
    SELECT ?country (MAX(?count2) AS ?maxCount) WHERE {
      {
        SELECT ?country ?day2 (COUNT(?election2) AS ?count2) WHERE {
          ?election2 wdt:P31/wdt:P279* wd:Q40231;
                     wdt:P17 ?country;
                     wdt:P585 ?date2.
        BIND(WEEKDAY(?date2) AS ?weekdayNum2)
        BIND(
          IF(?weekdayNum2 = 0, wd:Q127,
          IF(?weekdayNum2 = 1, wd:Q128,
          IF(?weekdayNum2 = 2, wd:Q129,
          IF(?weekdayNum2 = 3, wd:Q130,
          IF(?weekdayNum2 = 4, wd:Q131,
          IF(?weekdayNum2 = 5, wd:Q132, wd:Q133))))))
          AS ?day2
        )
        }
        GROUP BY ?country ?day2
      }
    }
    GROUP BY ?country
  }
  FILTER(?count = ?maxCount)
  BIND(?count AS ?electionCount)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?electionCount) ?countryLabel ?dayLabel

SELECT DISTINCT ?church1 ?church1Label ?church2 ?church2Label ?location1 ?location2 ?distanceKm WHERE {
  VALUES ?uk { wd:Q145 }
  ?church1 wdt:P31/wdt:P279* wd:Q16970 ;
           wdt:P17 ?uk ;
           wdt:P625 ?location1 .
  ?church2 wdt:P31/wdt:P279* wd:Q16970 ;
           wdt:P17 ?uk ;
           wdt:P625 ?location2 .
  FILTER(?church1 != ?church2)
  FILTER(STR(?church1) < STR(?church2))
  BIND(geof:distance(?location1, ?location2) AS ?distance)
  BIND(?distance / 1000 AS ?distanceKm)
  FILTER(?distance < 0.1)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distanceKm ?church1Label ?church2Label

