SELECT ?year ?stageNumber ?stageLabel ?winnerLabel ?winnerNationalityLabel WHERE {
  {
    SELECT ?edition ?year ?stage ?stageNumber ?winner ?winnerNationality WHERE {
      ?edition wdt:P31 wd:Q15991247;
               wdt:P361 wd:Q33814;
               wdt:P585 ?date.
      BIND(YEAR(?date) AS ?year)
      FILTER(?year >= 1903 && ?year <= 2022)

      ?stage wdt:P31/wdt:P279* wd:Q15254495;
             wdt:P361 ?edition;
             p:P1346 ?winnerStatement.
      ?winnerStatement ps:P1346 ?winner.
      OPTIONAL { ?winner wdt:P27 ?winnerNationality. }

      OPTIONAL { ?stage wdt:P1545 ?stageNumberString. }
