    FILTER(?ps IN (ps:P569, ps:P570))
    BIND(IF(?ps = ps:P569, wd:Q1190554, wd:Q মৃত্যু) AS ?event)
    OPTIONAL { ?statement pq:P276 ?place . }
    BIND(?eventValue AS ?date)
