           wdt:P179 wd:Q216269;
           wdt:P921 ?subject.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?episodeLabel ?subjectLabel

SELECT ?person ?personLabel ?birthYear ?deathYear ?birthPlace ?birthPlaceLabel ?deathPlace ?deathPlaceLabel WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P569 ?birthDate;
          wdt:P570 ?deathDate;
          wdt:P19 ?birthPlace;
          wdt:P20 ?deathPlace.
  BIND(YEAR(?birthDate) AS ?birthYear)
  BIND(YEAR(?deathDate) AS ?deathYear)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?name ?municipality ?municipalityLabel ?coord ?otherMunicipality ?otherMunicipalityLabel ?otherCoord ?distance WHERE {
  {
    SELECT ?name ?municipality ?otherMunicipality ?coord ?otherCoord
           (geof:distance(?coord, ?otherCoord) AS ?distance)
    WHERE {
      ?municipality wdt:P31/wdt:P279* wd:Q484170;
                    rdfs:label ?name;
                    wdt:P625 ?coord;
                    wdt:P17 wd:Q142.
      FILTER(LANG(?name) = "fr")

      ?otherMunicipality wdt:P31/wdt:P279* wd:Q484170;
                         rdfs:label ?name;
                         wdt:P625 ?otherCoord;
                         wdt:P17 wd:Q142.

      FILTER(?municipality != ?otherMunicipality)
      FILTER(STR(?municipality) < STR(?otherMunicipality))
    }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "fr,en". }
} ORDER BY ?name ?distance

SELECT DISTINCT ?place ?placeLabel ?welshLabel ?coord WHERE {
  ?place wdt:P625 ?coord .
  OPTIONAL {
    ?place rdfs:label ?placeLabel .
    FILTER(LANG(?placeLabel) = "en")
  }
  OPTIONAL {
    ?place rdfs:label ?welshLabel .
    FILTER(LANG(?welshLabel) = "cy")
  }
  FILTER(BOUND(?placeLabel) && BOUND(?welshLabel))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?property ?propertyLabel ?count WHERE {
  {
    SELECT ?property (COUNT(*) AS ?count) WHERE {
      ?map wdt:P31/wdt:P279* wd:Q4006 .
      ?map ?p ?value .
      ?property wikibase:directClaim ?p .
      FILTER(STRSTARTS(STR(?p), STR(wdt:)))
    }
    GROUP BY ?property
    ORDER BY DESC(?count)
    LIMIT 50
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?count)

SELECT ?museum ?museumLabel ?location ?distance WHERE {
