  VALUES ?type {
    wd:Q16917      # hospital
    wd:Q875538     # clinic
    wd:Q2590631    # health center
    wd:Q4287745    # medical college
    wd:Q1059324    # nursing home
    wd:Q7075       # sanatorium
    wd:Q1774898    # dispensary
    wd:Q1244766    # pharmacy
  }

  ?facility wdt:P31/wdt:P279* ?type ;
            wdt:P131* wd:Q1940572 ;
            wdt:P625 ?coord .

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?grave ?graveLabel ?person ?personLabel ?deathDate WHERE {
  ?person wdt:P119 wd:Q311 ;
          wdt:P570 ?deathDate .
  FILTER(?deathDate >= "1800-01-01T00:00:00Z"^^xsd:dateTime &&
         ?deathDate < "1850-01-01T00:00:00Z"^^xsd:dateTime)

  ?grave wdt:P31/wdt:P279* wd:Q29642950 ;
         wdt:P361 wd:Q311 ;
         wdt:P547 ?person .

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel ?age WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P27 wd:Q38;
          wdt:P106 wd:Q82955;
          p:P39 ?statement.
  ?statement ps:P39 ?position.
  ?position wdt:P279* wd:Q83307.
  ?person wdt:P569 ?birthDate.

  BIND(YEAR(NOW()) - YEAR(?birthDate) - IF((MONTH(NOW()) < MONTH(?birthDate)) || ((MONTH(NOW()) = MONTH(?birthDate)) && (DAY(NOW()) < DAY(?birthDate))), 1, 0) AS ?age)
  FILTER(?age >= 50 && ?age <= 80)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?personLabel

SELECT ?president ?presidentLabel ?start WHERE {
  ?president p:P39 ?statement .
  ?statement ps:P39 wd:Q11696 ;
             pq:P580 ?start .
  ?president wdt:P31 wd:Q5 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?start

