  VALUES ?item { wd:Q61763686 wd:Q4505691 }
  ?item wdt:P18 ?image .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?genderLabel (COUNT(DISTINCT ?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P21 ?gender;
          p:P166 ?awardStatement.
  ?awardStatement ps:P166 ?award.
  ?award wdt:P31/wdt:P279* wd:Q618779.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?genderLabel
ORDER BY DESC(?count)

SELECT ?region ?regionLabel ?coord ?percent WHERE {
  ?region wdt:P31/wdt:P279* wd:Q82794;
          wdt:P17 wd:Q145;
          wdt:P625 ?coord.
  FILTER(CONTAINS(LCASE(?regionLabel), "wales")) # placeholder to bias toward Welsh regions
  OPTIONAL { ?region wdt:P1098 ?population. }
  OPTIONAL { ?region p:P1098 ?popStmt. ?popStmt ps:P1098 ?population. }
  OPTIONAL { ?region wdt:P1082 ?totalPopulation. }
  OPTIONAL { ?region wdt:P2937 ?welshSpeakers. }
  BIND(
    IF(BOUND(?welshSpeakers) && BOUND(?totalPopulation) && ?totalPopulation > 0,
       (100 * ?welshSpeakers / ?totalPopulation),
       ?percent
    ) AS ?percent
  )
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?language ?languageLabel ?country ?countryLabel WHERE {
  ?language wdt:P31 wd:Q34770;
            wdt:P17 ?country.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?countryLabel ?languageLabel

SELECT ?streetName (COUNT(?street) AS ?count) WHERE {
