          wdt:P131* wd:Q64.
  FILTER(LANG(?streetName) = "en")
}
GROUP BY ?streetName
HAVING (COUNT(?street) > 1)
ORDER BY DESC(?count) ?streetName

SELECT ?person ?personLabel ?dateOfBirth WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P569 ?dateOfBirth.

  FILTER(MONTH(?dateOfBirth) = 1)
  FILTER(
    ((YEAR(?dateOfBirth) % 4 = 0) && (YEAR(?dateOfBirth) % 100 != 0)) ||
    (YEAR(?dateOfBirth) % 400 = 0)
  )

  ?person wdt:P106 ?occupation.

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

