SELECT ?restaurant ?restaurantLabel ?coord WHERE {
  ?restaurant wdt:P31/wdt:P279* wd:Q11707;      # instance of restaurant (or subclass)
              wdt:P131* wd:Q39;                 # located in Switzerland
              wdt:P625 ?coord;                  # coordinates for map
