SELECT DISTINCT ?person ?personLabel ?deathDate WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P570 ?deathDate.
  FILTER(?deathDate >= "1969-01-01T00:00:00Z"^^xsd:dateTime &&
         ?deathDate <  "1971-01-01T00:00:00Z"^^xsd:dateTime)
  ?person wikibase:sitelinks ?sitelinks.
  FILTER(?sitelinks > 50)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?deathDate

SELECT ?headOfGovernment ?headOfGovernmentLabel ?positionLabel ?start ?end ?durationDays WHERE {
  {
    SELECT ?headOfGovernment ?position ?start ?end
           ((COALESCE(?end, NOW()) - ?start) AS ?duration)
           (xsd:decimal((COALESCE(?end, NOW()) - ?start) / 86400) AS ?durationDays)
    WHERE {
      VALUES ?country { wd:Q142 }  # France
      ?statement ps:P6 ?headOfGovernment ;
                 pq:P580 ?start .
      wd:Q142 p:P6 ?statement .
      OPTIONAL { ?statement pq:P582 ?end . }
      OPTIONAL { ?statement pq:P39 ?position . }
    }
    ORDER BY DESC(?duration)
    LIMIT 10
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY DESC(?durationDays)

SELECT DISTINCT ?route ?routeLabel ?coord WHERE {
  ?route wdt:P31/wdt:P279* wd:Q2175765 ;
         wdt:P17 wd:Q142 ;
         wdt:P625 ?coord .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?opening ?openingLabel (COUNT(?site) AS ?siteLinks) WHERE {
  ?opening wdt:P31 wd:Q23038190.
  ?site schema:about ?opening .
  FILTER(SUBSTR(STR(?site), 1, 25) = "https://")
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?opening ?openingLabel
ORDER BY DESC(?siteLinks)
LIMIT 50

SELECT ?country ?countryLabel ?painting ?paintingLabel WHERE {
  {
    SELECT ?country ?painting (COUNT(?article) AS ?sitelinks) WHERE {
      ?painting wdt:P31/wdt:P279* wd:Q3305213;
                wdt:P17 ?country.
      ?article schema:about ?painting;
               schema:isPartOf ?wiki.
      FILTER(CONTAINS(STR(?wiki), "wikipedia.org"))
    }
    GROUP BY ?country ?painting
  }
  {
    SELECT ?country (MAX(?count) AS ?maxSitelinks) WHERE {
      {
        SELECT ?country ?painting (COUNT(?article) AS ?count) WHERE {
          ?painting wdt:P31/wdt:P279* wd:Q3305213;
                    wdt:P17 ?country.
          ?article schema:about ?painting;
                   schema:isPartOf ?wiki.
          FILTER(CONTAINS(STR(?wiki), "wikipedia.org"))
        }
        GROUP BY ?country ?painting
      }
    }
    GROUP BY ?country
  }
  FILTER(?sitelinks = ?maxSitelinks)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?countryLabel ?paintingLabel

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P21 wd:Q6581072;
          wdt:P27 wd:Q258.
  FILTER EXISTS {
    ?article schema:about ?person;
             schema:isPartOf <https://en.wikipedia.org/>.
  }
  FILTER NOT EXISTS {
    ?quotePage schema:about ?person;
