    wd:Q308    # Venus
    wd:Q2      # Earth
    wd:Q111    # Mars
    wd:Q319    # Jupiter
    wd:Q193    # Saturn
    wd:Q324    # Uranus
    wd:Q332    # Neptune
  }
  ?moon wdt:P31 wd:Q2537;
        wdt:P397 ?planet.
  OPTIONAL { ?moon wdt:P138 ?namesake. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
