SELECT DISTINCT ?monument ?monumentLabel ?person ?personLabel WHERE {
  ?monument wdt:P31/wdt:P279* wd:Q4989906;
            rdfs:label ?monumentLabel.
  FILTER(LANG(?monumentLabel) = "en")

  ?person rdfs:label ?personLabel.
  FILTER(LANG(?personLabel) = "en")

  FILTER(CONTAINS(LCASE(?monumentLabel), LCASE(?personLabel)))

  FILTER NOT EXISTS { ?monument ?p ?person. FILTER(?p != rdfs:label) }
  FILTER NOT EXISTS { ?person ?p2 ?monument }
}
LIMIT 100

