  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?astrolabe ?astrolabeLabel ?date ?diameter WHERE {
  ?astrolabe wdt:P31 wd:Q813672;
             wdt:P571 ?date;
             p:P2386 ?diameterStatement.
  ?diameterStatement ps:P2386 ?diameter.
  FILTER(datatype(?date) = xsd:dateTime || datatype(?date) = xsd:date)
