  ?child (wdt:P40|wdt:P22|wdt:P25)+ ?descendant .
  FILTER(?descendant != wd:Q842717)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?firstNameLabel (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P27 wd:Q142;
          p:P39 ?statement.
  ?statement ps:P39 ?position;
             pq:P580 ?start.
  FILTER(NOT EXISTS { ?statement pq:P582 ?end. })
  ?position wdt:P279* wd:Q16707842.
  ?person wdt:P735 ?firstName.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,fr". }
}
GROUP BY ?firstNameLabel
ORDER BY DESC(?count)
LIMIT 20

SELECT ?work ?workLabel ?publicationDate WHERE {
