  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?publicationDate ?workLabel

SELECT DISTINCT ?eventLabel ?date WHERE {
  VALUES ?person { wd:Q9711 }
  {
    ?person p:P569 ?stmt .
    ?stmt ps:P569 ?date .
    BIND("birth"@en AS ?eventLabel)
  }
  UNION
  {
    ?person p:P570 ?stmt .
    ?stmt ps:P570 ?date .
    BIND("death"@en AS ?eventLabel)
  }
  UNION
  {
    ?person p:P1196 ?stmt .
    ?stmt ps:P1196 ?date .
    BIND("manner of death date"@en AS ?eventLabel)
  }
  UNION
  {
    ?person p:P26 ?stmt .
    ?stmt pq:P580 ?date .
    BIND("marriage/start of spouse relationship"@en AS ?eventLabel)
  }
  UNION
  {
    ?person p:P39 ?stmt .
    ?stmt pq:P580 ?date .
    BIND("start of position held"@en AS ?eventLabel)
  }
  UNION
  {
    ?person p:P39 ?stmt .
    ?stmt pq:P582 ?date .
    BIND("end of position held"@en AS ?eventLabel)
  }
  UNION
  {
    ?person p:P551 ?stmt .
    ?stmt pq:P580 ?date .
    BIND("start of residence"@en AS ?eventLabel)
  }
  UNION
  {
    ?person p:P551 ?stmt .
    ?stmt pq:P582 ?date .
    BIND("end of residence"@en AS ?eventLabel)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?date

SELECT ?property ?propertyLabel WHERE {
