  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?population)

SELECT ?country ?countryLabel ?iso2 ?iso3 ?flag ?fertilityRate WHERE {
  ?country wdt:P31 wd:Q3624078 .
  OPTIONAL { ?country wdt:P297 ?iso2 . }
  OPTIONAL { ?country wdt:P298 ?iso3 . }
  OPTIONAL { ?country wdt:P41 ?flag . }
  OPTIONAL { ?country wdt:P4841 ?fertilityRate . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?type ?typeLabel (COUNT(?work) AS ?count) WHERE {
  ?work wdt:P31/wdt:P279* wd:Q7725634 .
  ?work wdt:P31 ?type .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?type ?typeLabel
ORDER BY DESC(?count)

SELECT ?decadeLabel ?placeOfBirthLabel (COUNT(DISTINCT ?person) AS ?winnerCount) WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P166 ?award;
          wdt:P569 ?birthDate;
          wdt:P19 ?placeOfBirth.
  ?award wdt:P31/wdt:P279* wd:Q37922.
  BIND(YEAR(?birthDate) AS ?year)
  BIND(CONCAT(STR(FLOOR(?year / 10) * 10), "s") AS ?decadeLabel)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?decadeLabel ?placeOfBirthLabel
ORDER BY ?decadeLabel DESC(?winnerCount)
